#!/usr/bin/env node
import { readFileSync } from 'node:fs'

const messagePath = process.argv[2]
if (!messagePath) {
  console.error('check-commit-msg: no commit message file given')
  process.exit(1)
}

const raw = readFileSync(messagePath, 'utf8')

// Comment lines are git's own scaffolding and never reach the final message.
const message = raw
  .split('\n')
  .filter((line) => !line.startsWith('#'))
  .join('\n')
  .trim()

const subject = message.split('\n')[0] ?? ''

// Merges and reverts are generated by git and carry whatever the original said.
const isGenerated = /^(Merge|Revert)\b/.test(subject)

const ISSUE_REFERENCE = /(^|\W)#\d+|(closes|fixes|resolves|refs?|issue)\s+#?\d+/i
const EMOJI = /\p{Extended_Pictographic}/u

const failures = []

if (!isGenerated && ISSUE_REFERENCE.test(message)) {
  failures.push(
    'Commit messages never reference an issue number. The branch name already carries it\n' +
      '  and the pull request body carries "Closes #<n>". Write "<type>: <summary>".'
  )
}

if (EMOJI.test(message)) {
  failures.push('Commit messages contain no emoji.')
}

if (failures.length > 0) {
  console.error('\nRejected commit message:\n')
  console.error(`  ${subject}\n`)
  failures.forEach((failure) => console.error(`- ${failure}`))
  console.error('')
  process.exit(1)
}
